const patient = $('Get Patient').first().json;
const clinic = $('Get Clinic Info').first().json;
const input = $('Validate Input (Patient)').first().json;
const clinicName = clinic.name || clinic.clinic_name || clinic.nombre || '';
const phone = '+' + String(patient.phone_number || '').replace(/\D/g, '');

return [{
  json: {
    phone,
    alert_instance_id: input.alert_instance_id || null,
    performed_by: input.performed_by || null,
    fields: {
      'patient.name': patient.name || '',
      'clinic.name': clinicName
    }
  }
}];

const patient = $('Get Patient').first().json;
const clinic = $('Get Clinic Info').first().json;
const appt = $('Get Appointment').first().json;
const input = $('Validate Input (Patient)').first().json;
const clinicName = clinic.name || clinic.clinic_name || clinic.nombre || '';
const phone = '+' + String(patient.phone_number || '').replace(/\D/g, '');

const start = new Date(appt.start_datetime);
const date = start.toLocaleDateString('es-UY', { day: 'numeric', month: 'long', year: 'numeric' });
const hour = start.toLocaleTimeString('es-UY', { hour: '2-digit', minute: '2-digit', hour12: false });

return [{
  json: {
    phone,
    alert_instance_id: input.alert_instance_id || null,
    performed_by: input.performed_by || null,
    fields: {
      'patient.name': patient.name || '',
      'clinic.name': clinicName,
      'appointment.date': date,
      'appointment.hour': hour,
      'appointment.professional_name': appt.professional_name || ''
    }
  }
}];

const patient = $('Get Patient').first().json;
const clinic = $('Get Clinic Info').first().json;
const inv = $('Get Invoice').first().json;
const input = $('Validate Input (Patient)').first().json;
const clinicName = clinic.name || clinic.clinic_name || clinic.nombre || '';
const phone = '+' + String(patient.phone_number || '').replace(/\D/g, '');

const pending = (Number(inv.total) - Number(inv.paid_amount || 0)).toFixed(2);
const amountFormatted = `${inv.currency || ''} ${pending}`.trim();
const dueDateFormatted = new Date(inv.due_date).toLocaleDateString('es-UY', { day: 'numeric', month: 'long', year: 'numeric' });

return [{
  json: {
    phone,
    alert_instance_id: input.alert_instance_id || null,
    performed_by: input.performed_by || null,
    fields: {
      'patient.name': patient.name || '',
      'clinic.name': clinicName,
      'invoice.doc_no': inv.doc_no || '',
      'invoice.amount_formatted': amountFormatted,
      'invoice.due_date_formatted': dueDateFormatted
    }
  }
}];

// Shared merge point: both entry webhooks land here with the same shape
// { phone, meta_template_name, meta_language, meta_template_name_sql, meta_language_sql, parameters, alert_instance_id, performed_by }.
return $input.all();

const input = $input.first().json;
const body = input.body || {};
const patientId = String(body.patient_id || '').trim();
const appointmentId = String(body.appointment_id || '').trim();
const reason = String(body.reason || '').trim();

if (!patientId) {
  return [{ json: { __error: true, code: 403, message: 'patient_id is required' } }];
}

if (!appointmentId) {
  return [{ json: { __error: true, code: 400, message: 'appointment_id is required' } }];
}

return [{
  json: {
    patient_id: patientId,
    appointment_id: appointmentId,
    reason: reason
  }
}];

const loaded = $input.all().filter(r => r.json.id);
const input = $('Parse Cancel Appointment Input1').first().json;

if (loaded.length === 0) {
  return [{ json: { __error: true, code: 404, message: 'Cita no encontrada' } }];
}

const appt = loaded[0].json;

if (appt.patient_id !== input.patient_id) {
  return [{ json: { __error: true, code: 403, message: 'Esa cita no pertenece a este paciente' } }];
}

const status = String(appt.status || '').toLowerCase();
const TERMINAL = ['completed', 'cancelled', 'no_show', 'deleted'];
if (TERMINAL.includes(status)) {
  return [{ json: { __error: true, code: 409, message: `La cita ya está en estado '${status}' y no se puede cancelar` } }];
}

return [{ json: { ...input, from_status: status } }];

const input = $input.first().json;
const body = input.body || {};
const patientId = String(body.patient_id || '').trim();
const appointmentId = String(body.appointment_id || '').trim();
const desiredDate = String(body.desired_date || '').trim();
const desiredTime = String(body.desired_time || '').trim();

if (!patientId) {
  return [{ json: { __error: true, code: 403, message: 'patient_id is required' } }];
}

if (!appointmentId || !desiredDate || !desiredTime) {
  return [{ json: { __error: true, code: 400, message: 'appointment_id, desired_date and desired_time are required' } }];
}

return [{
  json: {
    patient_id: patientId,
    appointment_id: appointmentId,
    desired_date: desiredDate,
    desired_time: desiredTime
  }
}];

const loaded = $input.all().filter(r => r.json.id);
const input = $('Parse Update Appointment Input1').first().json;

if (loaded.length === 0) {
  return [{ json: { __error: true, code: 404, message: 'Cita no encontrada' } }];
}

const appt = loaded[0].json;

if (appt.patient_id !== input.patient_id) {
  return [{ json: { __error: true, code: 403, message: 'Esa cita no pertenece a este paciente' } }];
}

const status = String(appt.status || '').toLowerCase();
const TERMINAL = ['completed', 'cancelled', 'no_show', 'deleted'];
if (TERMINAL.includes(status)) {
  return [{ json: { __error: true, code: 409, message: `La cita ya está en estado '${status}' y no se puede reagendar` } }];
}

const durationMinutes = Math.round((new Date(appt.end_datetime).getTime() - new Date(appt.start_datetime).getTime()) / 60000) || 30;

return [{
  json: {
    ...input,
    from_status: status,
    original_assignee_id: appt.assignee_id,
    original_calendar_source_id: appt.calendar_source_id,
    duration_minutes: durationMinutes,
    summary: appt.summary,
    notes: appt.notes
  }
}];

const ctx = $('Validate Reschedule Eligibility1').first().json;
const calendarSourceIds = $input.first().json.calendar_source_ids || '';

const start = new Date(`${ctx.desired_date}T${ctx.desired_time}:00`);
const end = new Date(start.getTime() + ctx.duration_minutes * 60000);

return [{
  json: {
    startingDateAndTime: start.toISOString().replace('Z', ''),
    endingDateAndTime: end.toISOString().replace('Z', ''),
    durationInMinutes: ctx.duration_minutes,
    mode: 'checkAvailability',
    calendarSourceIds,
    appointmentId: ctx.appointment_id,
    doctorId: ctx.original_assignee_id || '',
    patientId: ctx.patient_id
  }
}];

const ctx = $('Build Availability Request (Reschedule)1').first().json;
const result = $input.first().json;

const isAvailable = result?.isAvailable === true;

let chosen = null;
if (isAvailable) {
  const startIso = result.availableStartingTime;
  chosen = {
    assignee_id: result.availableDoctorId,
    assignee_name: result.availableDoctorName,
    calendar_source_id: result.availableCalendarSourceId,
    calendar_name: result.availableCalendarName,
    date: startIso ? startIso.slice(0, 10) : ctx.startingDateAndTime.slice(0, 10),
    time: startIso ? startIso.slice(11, 16) : ctx.startingDateAndTime.slice(11, 16)
  };
}

const suggestions = (result?.suggestedTimes || []).map((s) => ({
  assignee_id: s.user_id,
  assignee_name: s.user_name,
  calendar_source_id: s.calendar_source_id,
  calendar_name: s.calendar_name,
  date: s.fecha_cita,
  time: s.hora_cita
}));

return [{ json: { isAvailable, chosen, suggestions } }];

const summary = $('Get Account Summary1').all().map(i => i.json);
const detail = $('Get Account Detail1').all().map(i => i.json);

return [{
  json: {
    by_currency: summary,
    pending_invoices: detail
  }
}];

const body = $input.first().json.body || {};
const isInboundText = body.type === 'whatsapp.inbound_message.received';

const msg = body.whatsappInboundMessage || body.whatsappMessage || {};
const textBody = msg.text?.body;
const wamid = msg.wamid || msg.id || '';
const fromPhone = msg.from || '';

const isTextMessage = isInboundText && typeof textBody === 'string' && textBody.trim() !== '' && !!wamid && !!fromPhone;
const normalizedPhone = '+' + String(fromPhone || '').replace(/\D/g, '');

return [{
  json: {
    is_text_message: isTextMessage,
    wamid,
    from_phone: normalizedPhone,
    message_text: textBody || ''
  }
}];

const patient = $input.first().json || {};
const extract = $('Filter & Extract Inbound Message').first().json;

const isKnownPatient = !!patient.id;

return [{
  json: {
    patient_id: patient.id || null,
    patient_name: patient.name || '',
    is_known_patient: isKnownPatient,
    phone: extract.from_phone,
    message_text: extract.message_text
  }
}];

const input = $input.first().json;
const body = input.body || {};
const patientId = String(body.patient_id || '').trim();
const serviceName = String(body.service_name || '').trim();
const desiredDate = String(body.desired_date || '').trim();
const desiredTime = String(body.desired_time || '').trim();
const sedeId = String(body.sede_id || '').trim();

if (!patientId) {
  return [{ json: { __error: true, code: 403, message: 'patient_id is required' } }];
}

if (!serviceName || !desiredDate) {
  return [{ json: { __error: true, code: 400, message: 'service_name and desired_date are required' } }];
}

if (!sedeId) {
  return [{ json: { __error: true, code: 400, message: 'sede_id is required — use list_sedes first' } }];
}

return [{
  json: {
    patient_id: patientId,
    service_name: serviceName,
    preferred_doctor_name: body.preferred_doctor_name || '',
    desired_date: desiredDate,
    desired_time: desiredTime,
    sede_id: sedeId
  }
}];

const ctx = $('Resolve Service & Window').first().json;
const service = $('Find Service').first().json;
const preferredDoctor = $('Find Preferred Doctor').first().json;
const calendarSourceIds = $input.first().json.calendar_source_ids || '';

const durationMinutes = Number(service?.duration_minutes) || 30;
const start = ctx.desired_time
  ? new Date(`${ctx.desired_date}T${ctx.desired_time}:00`)
  : new Date(`${ctx.desired_date}T09:00:00`);
const end = new Date(start.getTime() + durationMinutes * 60000);

return [{
  json: {
    startingDateAndTime: start.toISOString().replace('Z', ''),
    endingDateAndTime: end.toISOString().replace('Z', ''),
    durationInMinutes: durationMinutes,
    mode: 'checkAvailability',
    calendarSourceIds,
    appointmentId: '',
    doctorId: preferredDoctor.id || '',
    patientId: ctx.patient_id,
    service
  }
}];

const request = $('Build Availability Request').first().json;
const service = request.service;
const result = $input.first().json;

const isAvailable = result?.isAvailable === true;

let chosen = null;
if (isAvailable) {
  const startIso = result.availableStartingTime;
  chosen = {
    assignee_id: result.availableDoctorId,
    assignee_name: result.availableDoctorName,
    calendar_source_id: result.availableCalendarSourceId,
    calendar_name: result.availableCalendarName,
    date: startIso ? startIso.slice(0, 10) : request.startingDateAndTime.slice(0, 10),
    time: startIso ? startIso.slice(11, 16) : request.startingDateAndTime.slice(11, 16)
  };
}

const suggestions = (result?.suggestedTimes || []).map((s) => ({
  assignee_id: s.user_id,
  assignee_name: s.user_name,
  calendar_source_id: s.calendar_source_id,
  calendar_name: s.calendar_name,
  date: s.fecha_cita,
  time: s.hora_cita
}));

return [{ json: {
  service: { name: service?.name, duration_minutes: service?.duration_minutes, price: service?.price, currency: service?.currency },
  isAvailable,
  chosen,
  suggestions
} }];

const input = $input.first().json;
const body = input.body || {};
const patientId = String(body.patient_id || '').trim();
const required = ['assignee_id', 'date', 'time', 'service_name'];
const missing = required.filter((k) => !body[k]);
if (!patientId) missing.unshift('patient_id');

if (missing.length > 0) {
  return [{ json: { __error: true, code: 400, message: `Missing required fields: ${missing.join(', ')}` } }];
}

return [{
  json: {
    patient_id: patientId,
    assignee_id: body.assignee_id,
    calendar_source_id: body.calendar_source_id,
    date: body.date,
    time: body.time,
    service_name: body.service_name,
    notes: String(body.notes || '').trim()
  }
}];

const input = $('Parse Create Appointment Input').first().json;
const service = $input.first().json;

const durationMinutes = Number(service.duration_minutes) || 30;
const start = new Date(`${input.date}T${input.time}:00`);
const end = new Date(start.getTime() + durationMinutes * 60 * 1000);

const toLocalTimestamp = (d) => d.toISOString().replace('Z', '');

return [{
  json: {
    ...input,
    start_datetime: toLocalTimestamp(start),
    end_datetime: toLocalTimestamp(end)
  }
}];

const ctx = $('Compute Datetime Range').first().json;
const doctorInfo = $input.first().json;
const durationMinutes = Math.round((new Date(ctx.end_datetime).getTime() - new Date(ctx.start_datetime).getTime()) / 60000);

return [{
  json: {
    startingDateAndTime: ctx.start_datetime,
    endingDateAndTime: ctx.end_datetime,
    durationInMinutes: durationMinutes,
    mode: 'checkAvailability',
    calendarSourceIds: String(ctx.calendar_source_id || doctorInfo.calendar_source_id || ''),
    appointmentId: '',
    doctorId: ctx.assignee_id,
    patientId: ctx.patient_id
  }
}];

const ctx = $('Compute Datetime Range').first().json;
const doctorInfo = $('Get Assignee Info').first().json;
const result = $input.first().json;

const isAvailable = result?.isAvailable === true;
const resolvedCalendarSourceId = ctx.calendar_source_id || doctorInfo.calendar_source_id;

const suggestions = (result?.suggestedTimes || []).map((s) => ({
  assignee_id: s.user_id,
  assignee_name: s.user_name,
  calendar_source_id: s.calendar_source_id,
  calendar_name: s.calendar_name,
  date: s.fecha_cita,
  time: s.hora_cita
}));

return [{ json: { ...ctx, calendar_source_id: resolvedCalendarSourceId, is_available: isAvailable, suggestions } }];

