INSERT INTO appointments (patient_id, assignee_id, calendar_source_id, start_datetime, end_datetime, status, summary, notes)
VALUES ($1::uuid, $2::uuid, $3::bigint, $4::timestamp, $5::timestamp, 'scheduled', $6, COALESCE(NULLIF($7, ''), 'Agendado automáticamente por el asistente de WhatsApp'))
RETURNING id, start_datetime, end_datetime;

